import React, { useState } from 'react';
import { SITE_INFO } from '../data/site';

export const ContactPage: React.FC = () => {
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setSubmitted(true);
  };

  return (
    <div className="min-h-screen bg-[#0B0B0B] text-white pt-32 pb-24 px-4 sm:px-8">
      <div className="max-w-4xl mx-auto">
        <div className="text-center mb-16">
          <span className="text-xs uppercase tracking-widest text-[#E8184D] font-bold block mb-3">Get in Touch</span>
          <h1 className="text-4xl sm:text-7xl font-black uppercase tracking-tight mb-6">Contact <span className="serif-italic text-[#E8184D]">Us</span></h1>
          <p className="text-lg text-white/70">We are open 24 hours to serve you across Hyderabad and Sindh.</p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
          {/* Contact Details */}
          <div className="glass-panel p-8 rounded-3xl space-y-6">
            <h3 className="text-2xl font-black uppercase text-[#E8184D]">Reach Out</h3>
            <p className="text-sm text-white/70 font-light">{SITE_INFO.corporateOffice}</p>
            <div className="space-y-3 text-sm">
              <p>UAN: <a href="tel:111666212" className="text-[#E8184D] font-bold">{SITE_INFO.uan}</a></p>
              <p>WhatsApp: <a href={SITE_INFO.whatsappUrl} target="_blank" rel="noopener noreferrer" className="text-[#E8184D] font-bold">{SITE_INFO.phone}</a></p>
              <p>Email: <a href={`mailto:${SITE_INFO.email}`} className="text-[#E8184D]">{SITE_INFO.email}</a></p>
            </div>
          </div>

          {/* Contact Form */}
          <div className="glass-panel p-8 rounded-3xl">
            <h3 className="text-2xl font-black uppercase mb-6 text-white">Send a Message</h3>
            {submitted ? (
              <div className="py-12 text-center text-[#E8184D] font-bold">Thank you! Your message has been received.</div>
            ) : (
              <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                  <label className="block text-xs uppercase font-bold text-white/60 mb-2">Your Name</label>
                  <input type="text" required className="w-full px-4 py-3 rounded-[2px] bg-black/50 border border-white/20 text-white text-sm focus:outline-none focus:border-[#E8184D]" />
                </div>
                <div>
                  <label className="block text-xs uppercase font-bold text-white/60 mb-2">Email or Phone</label>
                  <input type="text" required className="w-full px-4 py-3 rounded-[2px] bg-black/50 border border-white/20 text-white text-sm focus:outline-none focus:border-[#E8184D]" />
                </div>
                <div>
                  <label className="block text-xs uppercase font-bold text-white/60 mb-2">Message</label>
                  <textarea rows={4} required className="w-full px-4 py-3 rounded-[2px] bg-black/50 border border-white/20 text-white text-sm focus:outline-none focus:border-[#E8184D]"></textarea>
                </div>
                <button type="submit" className="w-full py-4 rounded-[2px] bg-[#E8184D] text-white font-bold text-xs uppercase tracking-widest hover:bg-white hover:text-black transition-colors">
                  Submit Inquiry
                </button>
              </form>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};