import React, { useState } from 'react';
import { OUTLETS, Outlet } from '../data/outlets';

export const OutletsSection: React.FC = () => {
  const [selectedCity, setSelectedCity] = useState("All");

  const cities = ["All", "Hyderabad", "Tando Jam", "Tando Adam", "Nawabshah", "Mirpurkhas", "Tando Allahyar"];

  const filteredOutlets = selectedCity === "All" ? OUTLETS : OUTLETS.filter(o => o.city.toLowerCase() === selectedCity.toLowerCase());

  return (
    <section className="py-24 px-4 sm:px-8 bg-[#0B0B0B]">
      <div className="max-w-7xl mx-auto mb-16 text-center">
        <span className="text-xs uppercase tracking-widest text-[#E8184D] font-bold block mb-3">20 Branches Strong</span>
        <h2 className="text-4xl sm:text-6xl font-black uppercase text-white tracking-tight mb-4">OUR <span className="serif-italic text-[#E8184D]">OUTLETS</span></h2>
        <p className="text-sm text-white/70 max-w-xl mx-auto">
          Our strongly proactive network is accessible to anyone, so our products get in your hands in a couple of minutes.
        </p>

        {/* City Filter Chips */}
        <div className="flex flex-wrap justify-center gap-2 mt-8">
          {cities.map((city) => (
            <button
              key={city}
              onClick={() => setSelectedCity(city)}
              className={`px-4 py-2 rounded-[2px] text-xs font-bold uppercase tracking-wider transition-all ${
                selectedCity === city ? 'bg-[#E8184D] text-white' : 'glass-panel text-white/70 hover:text-white'
              }`}
            >
              {city}
            </button>
          ))}
        </div>
      </div>

      <div className="max-w-7xl mx-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {filteredOutlets.map((outlet: Outlet) => (
          <div key={outlet.id} className="glass-panel p-8 rounded-3xl flex flex-col justify-between group hover:border-[#E8184D] transition-all">
            <div>
              <div className="flex justify-between items-center mb-4">
                <span className="text-xs font-bold uppercase px-3 py-1 bg-[#E8184D]/20 text-[#E8184D] rounded-full">
                  {outlet.city}
                </span>
                <span className="text-xs text-white/50">{outlet.hours}</span>
              </div>
              <h3 className="text-xl font-bold uppercase text-white mb-3 group-hover:text-[#E8184D] transition-colors">{outlet.name}</h3>
              <p className="text-sm text-white/70 mb-6 leading-relaxed font-light">{outlet.address}</p>
            </div>
            <div className="pt-4 border-t border-white/10 flex justify-between items-center">
              <a 
                href={`https://maps.google.com/?q=${encodeURIComponent(outlet.name + ' ' + outlet.address)}`} 
                target="_blank" 
                rel="noopener noreferrer"
                className="text-xs font-bold uppercase text-[#E8184D] hover:underline flex items-center gap-2"
              >
                <span>Get Directions</span>
                <span>→</span>
              </a>
              <span className="text-[10px] text-white/40">Open 24/7</span>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
};