import React, { useState } from 'react';
import { Routes, Route, useNavigate } from 'react-router-dom';
import { Header } from './components/Header';
import { MenuDrawer } from './components/MenuDrawer';
import { CommandPalette } from './components/CommandPalette';
import { Footer } from './components/Footer';
import { HomePage } from './pages/HomePage';
import { AboutPage } from './pages/AboutPage';
import { StoresPage } from './pages/StoresPage';
import { ContactPage } from './pages/ContactPage';
import { RewardsPage } from './pages/RewardsPage';
import { BlogsPage } from './pages/BlogsPage';
import { SocialWallPage } from './pages/SocialWallPage';
import { NotFoundPage } from './pages/NotFoundPage';
import { Product, CATEGORIES } from './data/catalog';
import { SITE_INFO } from './data/site';

export function App() {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [wishlist, setWishlist] = useState<Product[]>([]);
  const navigate = useNavigate();

  const handleSelectProduct = (product: Product) => {
    // Open WhatsApp order prefilled or navigate
    window.open(`${SITE_INFO.whatsappUrl}?text=I want to order ${product.name} (Rs. ${product.priceFrom})`, '_blank');
  };

  const handleSelectCategory = (slug: string) => {
    navigate(`/${slug}`);
  };

  return (
    <div className="min-h-screen bg-[#0B0B0B] text-white flex flex-col relative">
      {/* Film Grain overlay */}
      <div className="grain-overlay"></div>

      <Header 
        onOpenMenu={() => setIsMenuOpen(true)}
        onOpenSearch={() => setIsSearchOpen(true)}
        wishlistCount={wishlist.length}
      />

      <MenuDrawer 
        isOpen={isMenuOpen}
        onClose={() => setIsMenuOpen(false)}
        onSelectCategory={(slug) => {
          navigate('/');
          setTimeout(() => {
            const el = document.getElementById('menu-tunnel-section');
            el?.scrollIntoView({ behavior: 'smooth' });
          }, 100);
        }}
      />

      <CommandPalette 
        isOpen={isSearchOpen}
        onClose={() => setIsSearchOpen(false)}
        onSelectProduct={handleSelectProduct}
      />

      <div className="flex-grow">
        <Routes>
          <Route path="/" element={<HomePage onSelectProduct={handleSelectProduct} onSelectCategory={handleSelectCategory} />} />
          <Route path="/about-us" element={<AboutPage />} />
          <Route path="/our-stores" element={<StoresPage />} />
          <Route path="/contact-us" element={<ContactPage />} />
          <Route path="/rewards" element={<RewardsPage />} />
          <Route path="/blogs" element={<BlogsPage />} />
          <Route path="/social-wall" element={<SocialWallPage />} />
          {CATEGORIES.map(cat => (
            <Route 
              key={cat.slug} 
              path={`/${cat.slug}`} 
              element={<HomePage onSelectProduct={handleSelectProduct} onSelectCategory={handleSelectCategory} />} 
            />
          ))}
          <Route path="*" element={<NotFoundPage />} />
        </Routes>
      </div>

      <Footer />
    </div>
  );
}

export default App;