import React from 'react';
import { HeroCloud } from '../components/HeroCloud';
import { WeMakeMagic } from '../components/WeMakeMagic';
import { MenuTunnel } from '../components/MenuTunnel';
import { SignatureCards } from '../components/SignatureCards';
import { StatsSection } from '../components/StatsSection';
import { AppPromoSection } from '../components/AppPromoSection';
import { TestimonialsSection } from '../components/TestimonialsSection';
import { OutletsSection } from '../components/OutletsSection';
import { Product } from '../data/catalog';

interface HomePageProps {
  onSelectProduct: (product: Product) => void;
  onSelectCategory: (slug: string) => void;
}

export const HomePage: React.FC<HomePageProps> = ({ onSelectProduct, onSelectCategory }) => {
  return (
    <main className="w-full bg-[#0B0B0B] text-white">
      <HeroCloud onExploreTunnel={() => {
        const tunnelEl = document.getElementById('menu-tunnel-section');
        tunnelEl?.scrollIntoView({ behavior: 'smooth' });
      }} />
      <WeMakeMagic />
      <div id="menu-tunnel-section">
        <MenuTunnel onSelectProduct={onSelectProduct} />
      </div>
      <SignatureCards onSelectCategory={onSelectCategory} />
      <StatsSection />
      <AppPromoSection />
      <TestimonialsSection />
      <OutletsSection />
    </main>
  );
};