import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { CATEGORIES, Product } from '../data/catalog';

interface CommandPaletteProps {
  isOpen: boolean;
  onClose: () => void;
  onSelectProduct: (product: Product) => void;
}

export const CommandPalette: React.FC<CommandPaletteProps> = ({ isOpen, onClose, onSelectProduct }) => {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<Product[]>([]);
  const navigate = useNavigate();

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        if (isOpen) onClose();
      }
      if (e.key === 'Escape' && isOpen) {
        onClose();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose]);

  useEffect(() => {
    if (!query.trim()) {
      setResults([]);
      return;
    }
    const q = query.toLowerCase();
    const allProducts: Product[] = [];
    CATEGORIES.forEach(c => allProducts.push(...c.items));
    const filtered = allProducts.filter(p => 
      p.name.toLowerCase().includes(q) || 
      p.description.toLowerCase().includes(q) ||
      p.tagline.toLowerCase().includes(q) ||
      p.flavours.some(f => f.toLowerCase().includes(q))
    );
    setResults(filtered);
  }, [query]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center pt-20 px-4 bg-black/80 backdrop-blur-md animate-fadeIn">
      <div className="w-full max-w-2xl bg-[#121012] border border-white/20 rounded-2xl shadow-2xl overflow-hidden flex flex-col">
        {/* Search Input Bar */}
        <div className="flex items-center px-6 py-4 border-b border-white/10 gap-4">
          <svg className="w-5 h-5 text-[#E8184D]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
          <input
            type="text"
            placeholder="Search cakes, snacks, coffee, flavours..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            autoFocus
            className="w-full bg-transparent text-white placeholder-white/40 focus:outline-none text-lg font-medium"
          />
          <button onClick={onClose} className="text-xs text-white/50 hover:text-white px-2 py-1 bg-white/10 rounded">ESC</button>
        </div>

        {/* Results List */}
        <div className="max-h-96 overflow-y-auto p-4 flex flex-col gap-2">
          {query.trim() && results.length === 0 && (
            <div className="py-8 text-center text-white/50 text-sm">No products found matching "{query}"</div>
          )}

          {!query.trim() && (
            <div className="py-8 text-center text-white/40 text-sm">Type to search across our 586+ products...</div>
          )}

          {results.map((product) => (
            <div
              key={product.id}
              onClick={() => {
                onClose();
                onSelectProduct(product);
              }}
              className="flex items-center justify-between p-3 rounded-xl hover:bg-white/5 cursor-pointer transition-colors group border border-transparent hover:border-white/10"
            >
              <div className="flex items-center gap-4">
                <img src={product.image.src} alt={product.name} className="w-12 h-12 object-cover rounded-lg" />
                <div>
                  <h4 className="font-bold text-white group-hover:text-[#E8184D] transition-colors">{product.name}</h4>
                  <p className="text-xs text-white/60">{product.tagline}</p>
                </div>
              </div>
              <div className="text-right">
                <span className="text-sm font-bold text-[#E8184D]">Rs. {product.priceFrom}</span>
                <span className="block text-[10px] text-white/40 uppercase">{product.categorySlug}</span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};