import React from 'react';

export const SocialWallPage: React.FC = () => {
  const images = [
    "images/Chocolate drip cake.webp",
    "images/Cupcakes and donuts.webp",
    "images/Chocolate brownies.png",
    "images/Strawberry cream cake.png",
    "images/Gulab jamun.webp",
    "images/Tiered flower cake.webp"
  ];

  return (
    <div className="min-h-screen bg-[#0B0B0B] text-white pt-32 pb-24 px-4 sm:px-8">
      <div className="max-w-7xl mx-auto">
        <div className="text-center mb-16">
          <span className="text-xs uppercase tracking-widest text-[#E8184D] font-bold block mb-3">Instagram Wall</span>
          <h1 className="text-4xl sm:text-7xl font-black uppercase tracking-tight mb-6">Social <span className="serif-italic text-[#E8184D]">Wall</span></h1>
          <p className="text-lg text-white/70">Tag @blackandbrownbakers to get featured here.</p>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {images.map((img, idx) => (
            <div key={idx} className="glass-panel rounded-3xl overflow-hidden aspect-square p-2 group relative">
              <img src={img} alt="Social post" className="w-full h-full object-cover rounded-2xl group-hover:scale-105 transition-transform duration-500" />
              <div className="absolute inset-2 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity rounded-2xl flex items-center justify-center">
                <span className="text-xs font-bold uppercase text-white bg-[#E8184D] px-4 py-2 rounded-full">View on Instagram</span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};