import React from 'react';
import { TESTIMONIALS } from '../data/site';

export const TestimonialsSection: React.FC = () => {
  return (
    <section className="py-24 px-4 sm:px-8 bg-[#121012]">
      <div className="max-w-7xl mx-auto mb-16 text-center">
        <span className="text-xs uppercase tracking-widest text-[#E8184D] font-bold block mb-3">Customer Love</span>
        <h2 className="text-4xl sm:text-6xl font-black uppercase text-white tracking-tight">Our Happy <span className="serif-italic text-[#E8184D]">Customers</span></h2>
      </div>

      <div className="max-w-7xl mx-auto grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
        {TESTIMONIALS.map((t) => (
          <div key={t.id} className="glass-panel p-8 rounded-3xl flex flex-col justify-between hover:border-[#E8184D] transition-all">
            <div>
              <div className="flex text-[#E8184D] mb-4 text-sm">★★★★★</div>
              <p className="text-sm text-white/80 leading-relaxed mb-6 font-light">"{t.comment}"</p>
            </div>
            <div className="flex items-center gap-4 pt-4 border-t border-white/10">
              <img src={t.avatar} alt={t.name} className="w-12 h-12 rounded-full object-cover" />
              <div>
                <h4 className="font-bold text-white">{t.name}</h4>
                <span className="text-xs text-[#E8184D]">{t.role}</span>
              </div>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
};