import React from 'react';
import { SITE_INFO } from '../data/site';

export const StatsSection: React.FC = () => {
  return (
    <section className="py-20 px-4 sm:px-8 bg-[#121012] border-y border-white/10">
      <div className="max-w-7xl mx-auto grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8 text-center">
        {SITE_INFO.stats.map((stat, idx) => (
          <div key={idx} className="glass-panel p-8 rounded-3xl relative overflow-hidden group hover:border-[#E8184D] transition-all">
            <div className="absolute -right-10 -bottom-10 w-32 h-32 bg-[#E8184D]/10 rounded-full blur-2xl group-hover:bg-[#E8184D]/20 transition-all"></div>
            <span className="text-5xl sm:text-6xl font-black italic text-white block mb-2">{stat.value}</span>
            <span className="text-xs uppercase tracking-widest text-[#E8184D] font-bold">{stat.label}</span>
          </div>
        ))}
      </div>
    </section>
  );
};